from pathlib import Path
import sys
root=Path(sys.argv[1])
api=root/'api'

api_php=r'''<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
$caller=require_auth();$ctx=user_context();
if(($ctx['role']??'')!=='master')out(['data'=>null,'error'=>['message'=>'Somente o MASTER pode acessar a limpeza de dados.']],403);
function t_exists($t){static $c=[];if(isset($c[$t]))return$c[$t];try{$q=db()->prepare("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?");$q->execute([$t]);return$c[$t]=(int)$q->fetchColumn()>0;}catch(Throwable$e){return$c[$t]=false;}}
function c_exists($t,$c){static $x=[];$k=$t.'.'.$c;if(isset($x[$k]))return$x[$k];try{$q=db()->prepare("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?");$q->execute([$t,$c]);return$x[$k]=(int)$q->fetchColumn()>0;}catch(Throwable$e){return$x[$k]=false;}}
function valid_date($d){$x=DateTime::createFromFormat('Y-m-d',$d);if(!$x||$x->format('Y-m-d')!==$d)throw new RuntimeException('Data limite inválida.');if($d>=date('Y-m-d'))throw new RuntimeException('A data limite precisa ser anterior a hoje.');return$d;}
function church($id){$q=db()->prepare('SELECT id,nome FROM igrejas WHERE id=? LIMIT 1');$q->execute([$id]);return$q->fetch(PDO::FETCH_ASSOC)?:null;}
function cnt($sql,$a){try{$q=db()->prepare($sql);$q->execute($a);return(int)$q->fetchColumn();}catch(Throwable$e){return 0;}}
function preview($ig,$d,$scope){$a=[$ig,$d];$x=[];$x['escalas']=cnt('SELECT COUNT(*) FROM escalas e WHERE e.igreja_id=? AND e.data<=?',$a);$x['itens']=cnt('SELECT COUNT(*) FROM escala_itens ei JOIN escalas e ON e.id=ei.escala_id WHERE e.igreja_id=? AND e.data<=?',$a);$x['checkins']=t_exists('checkins')?cnt('SELECT COUNT(*) FROM checkins c JOIN escalas e ON e.id=c.escala_id WHERE e.igreja_id=? AND e.data<=?',$a):0;$x['quiz']=t_exists('quiz_pos_culto')?cnt('SELECT COUNT(*) FROM quiz_pos_culto q JOIN escalas e ON e.id=q.escala_id WHERE e.igreja_id=? AND e.data<=?',$a):0;$x['avaliacoes']=t_exists('avaliacoes')?cnt('SELECT COUNT(*) FROM avaliacoes q JOIN escalas e ON e.id=q.escala_id WHERE e.igreja_id=? AND e.data<=?',$a):0;$x['justificativas']=t_exists('justificativas_ausencia')?cnt('SELECT COUNT(*) FROM justificativas_ausencia q JOIN escalas e ON e.id=q.escala_id WHERE e.igreja_id=? AND e.data<=?',$a):0;$x['trocas']=t_exists('trocas')?cnt('SELECT COUNT(*) FROM trocas t JOIN escala_itens ei ON ei.id=t.escala_item_id JOIN escalas e ON e.id=ei.escala_id WHERE e.igreja_id=? AND e.data<=?',$a):0;$x['jobs_whatsapp']=t_exists('whatsapp_send_jobs')?cnt('SELECT COUNT(*) FROM whatsapp_send_jobs w JOIN escalas e ON e.id=w.escala_id WHERE e.igreja_id=? AND e.data<=?',$a):0;return['scope'=>$scope,'cutoff'=>$d,'counts'=>$x,'affected'=>$scope==='completo'?$x['escalas']:$x['itens']];}
function storage_dir(){$d=__DIR__.'/../storage/master-cleanup/backups';if(!is_dir($d)&&!mkdir($d,0750,true)&&!is_dir($d))throw new RuntimeException('Não foi possível criar a pasta de backup.');$h=dirname($d).'/.htaccess';if(!is_file($h))@file_put_contents($h,"Require all denied\nDeny from all\n");return$d;}
function backup_db($name,$cutoff){$safe=preg_replace('/[^A-Za-z0-9_-]+/','-',iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$name)?:'igreja');$base=storage_dir().'/before-cleanup-'.trim($safe,'-').'-'.$cutoff.'-'.date('Ymd-His').'.sql';$gz=function_exists('gzopen');$path=$gz?$base.'.gz':$base;$h=$gz?gzopen($path,'wb6'):fopen($path,'wb');if(!$h)throw new RuntimeException('Não foi possível criar o backup automático.');$w=function($s)use($h,$gz){$gz?gzwrite($h,$s):fwrite($h,$s);};try{$w("-- Backup automático antes da limpeza MASTER\nSET NAMES utf8mb4;\nSET FOREIGN_KEY_CHECKS=0;\n");foreach(db()->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as$t){$st=str_replace('`','``',$t);$cr=db()->query('SHOW CREATE TABLE `'.$st.'`')->fetch(PDO::FETCH_NUM);if($cr&&isset($cr[1]))$w("\nDROP TABLE IF EXISTS `{$st}`;\n{$cr[1]};\n");$q=db()->query('SELECT * FROM `'.$st.'`');$cols=null;while($r=$q->fetch(PDO::FETCH_ASSOC)){if($cols===null)$cols=array_keys($r);$vals=[];foreach($r as$v)$vals[]=$v===null?'NULL':db()->quote((string)$v);$cs=implode(',',array_map(fn($c)=>'`'.str_replace('`','``',$c).'`',$cols));$w('INSERT INTO `'.$st.'` ('.$cs.') VALUES ('.implode(',',$vals).");\n");}}$w("\nSET FOREIGN_KEY_CHECKS=1;\n");}catch(Throwable$e){$gz?gzclose($h):fclose($h);@unlink($path);throw$e;}$gz?gzclose($h):fclose($h);return$path;}
function runq($sql,$a,&$out,$key){$q=db()->prepare($sql);$q->execute($a);$out[$key]=($out[$key]??0)+$q->rowCount();}
function clean_presence($ig,$d){$a=[$ig,$d];$o=[];if(t_exists('checkins'))runq('DELETE c FROM checkins c JOIN escalas e ON e.id=c.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'checkins');if(t_exists('justificativas_ausencia'))runq('DELETE j FROM justificativas_ausencia j JOIN escalas e ON e.id=j.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'justificativas');$s=[];if(c_exists('escala_itens','status_confirmacao'))$s[]="ei.status_confirmacao='pendente'";foreach(['checkin_at','checkout_at','justificativa_recusa','justificativa_problema','problema_reportado_at']as$c)if(c_exists('escala_itens',$c))$s[]="ei.`$c`=NULL";if(c_exists('escala_itens','problema_reportado'))$s[]='ei.problema_reportado=0';if(c_exists('escala_itens','updated_at'))$s[]='ei.updated_at=NOW()';if($s)runq('UPDATE escala_itens ei JOIN escalas e ON e.id=ei.escala_id SET '.implode(',',$s).' WHERE e.igreja_id=? AND e.data<=?',$a,$o,'itens_resetados');return$o;}
function clean_all($ig,$d){$a=[$ig,$d];$o=[];if(t_exists('sos_candidates')&&t_exists('sos_requests'))runq('DELETE sc FROM sos_candidates sc JOIN sos_requests sr ON sr.id=sc.request_id JOIN escalas e ON e.id=sr.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'sos_candidates');if(t_exists('sos_requests'))runq('DELETE sr FROM sos_requests sr JOIN escalas e ON e.id=sr.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'sos_requests');if(t_exists('whatsapp_confirmation_contexts'))runq('DELETE w FROM whatsapp_confirmation_contexts w JOIN escalas e ON e.id=w.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'whatsapp_contextos');if(t_exists('whatsapp_swap_sessions'))runq('DELETE w FROM whatsapp_swap_sessions w JOIN escala_itens ei ON ei.id=w.escala_item_id JOIN escalas e ON e.id=ei.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'whatsapp_trocas');if(t_exists('whatsapp_send_jobs'))runq('DELETE w FROM whatsapp_send_jobs w JOIN escalas e ON e.id=w.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'jobs_whatsapp');if(t_exists('trocas'))runq('DELETE t FROM trocas t JOIN escala_itens ei ON ei.id=t.escala_item_id JOIN escalas e ON e.id=ei.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'trocas');if(t_exists('setlist_itens')&&t_exists('setlists'))runq('DELETE si FROM setlist_itens si JOIN setlists s ON s.id=si.setlist_id JOIN escalas e ON e.id=s.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'setlist_itens');foreach(['avaliacoes','quiz_pos_culto','justificativas_ausencia','checkins','setlists']as$t)if(t_exists($t))runq("DELETE x FROM `$t` x JOIN escalas e ON e.id=x.escala_id WHERE e.igreja_id=? AND e.data<=?",$a,$o,$t);runq('DELETE ei FROM escala_itens ei JOIN escalas e ON e.id=ei.escala_id WHERE e.igreja_id=? AND e.data<=?',$a,$o,'itens');runq('DELETE FROM escalas WHERE igreja_id=? AND data<=?',$a,$o,'escalas');return$o;}
$b=input_json();$action=(string)($b['action']??'status');try{if($action==='status'){out(['data'=>['churches'=>db()->query('SELECT id,nome FROM igrejas ORDER BY nome')->fetchAll(PDO::FETCH_ASSOC)],'error'=>null]);}$ig=trim((string)($b['igreja_id']??''));$d=valid_date(trim((string)($b['cutoff']??'')));$scope=(string)($b['scope']??'presenca');if(!in_array($scope,['presenca','completo'],true))throw new RuntimeException('Tipo de limpeza inválido.');$ch=church($ig);if(!$ch)throw new RuntimeException('Igreja não encontrada.');$p=preview($ig,$d,$scope);if($action==='preview')out(['data'=>['church'=>$ch]+$p,'error'=>null]);if($action!=='execute')throw new RuntimeException('Ação inválida.');if(trim((string)($b['confirmation']??''))!=='EXCLUIR')throw new RuntimeException('Digite EXCLUIR para confirmar.');if(($p['affected']??0)<1)throw new RuntimeException('Não há dados correspondentes aos filtros.');@set_time_limit(180);$backup=backup_db($ch['nome'],$d);$pdo=db();$pdo->beginTransaction();try{$del=$scope==='completo'?clean_all($ig,$d):clean_presence($ig,$d);$pdo->commit();}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}try{audit((string)($caller['id']??''),'master_data_cleanup',$scope,['igreja_id'=>$ig,'cutoff'=>$d,'deleted'=>$del,'backup'=>basename($backup)],'warning');}catch(Throwable$e){}out(['data'=>['success'=>true,'deleted'=>$del,'backup'=>basename($backup)],'error'=>null]);}catch(Throwable$e){out(['data'=>null,'error'=>['message'=>$e->getMessage()]],400);}'''
(api/'master-data-cleanup.php').write_text(api_php,encoding='utf-8')

html=r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Limpeza de dados — MASTER</title><style>*{box-sizing:border-box}body{margin:0;font:14px Arial,sans-serif;background:#f4f7fb;color:#172033}.w{max-width:1050px;margin:auto;padding:20px}.hero,.card{background:#fff;border:1px solid #dfe6ef;border-radius:18px;padding:18px}.hero{margin-bottom:14px}.hero h1{margin:0 0 6px}.warn{margin-top:12px;background:#fff6df;border:1px solid #efd28d;padding:12px;border-radius:12px;color:#755000}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.muted{color:#69788d}.card h2{margin:0 0 12px;font-size:17px}label{display:block;font-weight:700;font-size:12px;margin:12px 0 6px}select,input{width:100%;height:44px;border:1px solid #ccd7e5;border-radius:10px;padding:0 11px;background:#fff}.opt{display:flex;gap:9px;border:1px solid #dce4ee;padding:11px;border-radius:12px;margin:8px 0}.opt input{width:18px;height:18px}.opt span{font-size:12px;color:#6c788b}.btn{border:0;border-radius:10px;padding:12px 15px;font-weight:800;cursor:pointer}.primary{background:#1764e8;color:#fff}.danger{background:#c62828;color:#fff}.btn:disabled{opacity:.45}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0}.s{background:#f7f9fc;border:1px solid #e2e8f0;border-radius:10px;padding:10px}.s b{display:block;font-size:19px}.s small{color:#6c788b}.msg{margin-top:12px;padding:10px;border-radius:10px;display:none}.ok{display:block;background:#eaf8ef;color:#17643a}.err{display:block;background:#fff0f0;color:#9a2525}.info{display:block;background:#edf4ff;color:#234d89}.dangerbox{background:#fff5f5;border:1px solid #efb8b8;border-radius:12px;padding:12px;margin-top:12px}.preview{display:none}.result{white-space:pre-wrap;background:#111a29;color:#dbe7fa;padding:12px;border-radius:10px;margin-top:10px;font:12px monospace}@media(max-width:760px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.w{padding:12px}}</style></head><body><main class="w"><section class="hero"><h1>🧹 Limpeza de dados</h1><div class="muted">Exclusivo do MASTER para excluir históricos antigos de uma igreja.</div><div class="warn"><b>Atenção:</b> antes de excluir, o sistema cria automaticamente um backup completo do banco.</div></section><div class="grid"><section class="card"><h2>1. Escolha os dados</h2><label>Igreja / cliente</label><select id="church"><option>Carregando...</option></select><label>Excluir dados até esta data (inclusive)</label><input id="cutoff" type="date"><label>Tipo de limpeza</label><label class="opt"><input type="radio" name="scope" value="presenca" checked><div><b>Presença e check-in</b><br><span>Mantém as escalas, mas apaga check-in/check-out, justificativas e limpa confirmado/recusado/faltou/tarde.</span></div></label><label class="opt"><input type="radio" name="scope" value="completo"><div><b>Escalas antigas completas</b><br><span>Apaga as escalas e os dados vinculados: itens, check-ins, quiz, avaliações, trocas, SOS e filas WhatsApp.</span></div></label><button id="pv" class="btn primary" onclick="preview()">Pré-visualizar</button><div id="msg" class="msg"></div></section><section class="card"><h2>2. Conferência</h2><div id="empty" class="muted">Faça uma pré-visualização antes de excluir.</div><div id="preview" class="preview"><div id="summary"></div><div id="stats" class="stats"></div><div class="dangerbox"><b>Confirmação final</b><p class="muted">Digite <b>EXCLUIR</b> para liberar a exclusão.</p><input id="confirm" placeholder="EXCLUIR" oninput="unlock()"><br><br><button id="del" class="btn danger" disabled onclick="executeCleanup()">Excluir dados selecionados</button></div></div><div id="result"></div></section></div></main><script>const token=localStorage.getItem('escala-facil.auth-token')||'',H={'Content-Type':'application/json',Accept:'application/json',...(token?{Authorization:'Bearer '+token}:{})},$=x=>document.getElementById(x);let last=null;function msg(t,c='info'){$('msg').className='msg '+c;$('msg').textContent=t}async function api(b){const r=await fetch('/api/master-data-cleanup.php',{method:'POST',credentials:'include',headers:H,body:JSON.stringify(b)});let j={};try{j=await r.json()}catch{}if(!r.ok||j.error)throw new Error(j?.error?.message||'Falha na operação');return j.data}function scope(){return document.querySelector('input[name=scope]:checked').value}async function load(){try{const d=await api({action:'status'});$('church').innerHTML='<option value="">Selecione uma igreja</option>'+d.churches.map(x=>`<option value="${x.id}">${x.nome}</option>`).join('');let z=new Date();z.setMonth(z.getMonth()-6);$('cutoff').value=z.toISOString().slice(0,10)}catch(e){msg(e.message,'err')}}async function preview(){$('pv').disabled=true;try{last=await api({action:'preview',igreja_id:$('church').value,cutoff:$('cutoff').value,scope:scope()});$('empty').style.display='none';$('preview').style.display='block';$('confirm').value='';unlock();const c=last.counts;$('summary').innerHTML=`<b>${last.church.nome}</b> · até <b>${last.cutoff.split('-').reverse().join('/')}</b>`;let a=[['Escalas',c.escalas],['Itens',c.itens],['Check-ins',c.checkins],['Quiz',c.quiz],['Avaliações',c.avaliacoes],['Justificativas',c.justificativas],['Trocas',c.trocas],['WhatsApp',c.jobs_whatsapp]];$('stats').innerHTML=a.map(x=>`<div class=s><b>${x[1]||0}</b><small>${x[0]}</small></div>`).join('');msg('Confira os números antes de excluir.','ok')}catch(e){last=null;msg(e.message,'err')}finally{$('pv').disabled=false}}function unlock(){$('del').disabled=!last||$('confirm').value.trim()!=='EXCLUIR'}async function executeCleanup(){if(!last||!confirm(`Confirma a exclusão dos dados de ${last.church.nome} até ${last.cutoff}?`))return;$('del').disabled=true;msg('Criando backup e executando a limpeza...','info');try{const d=await api({action:'execute',igreja_id:$('church').value,cutoff:$('cutoff').value,scope:scope(),confirmation:'EXCLUIR'});msg('Limpeza concluída com sucesso.','ok');$('result').innerHTML=`<div class=result>Backup: ${d.backup}\n\n${JSON.stringify(d.deleted,null,2)}</div>`;last=null;$('preview').style.display='none';$('empty').style.display='block'}catch(e){msg(e.message,'err');unlock()}}document.querySelectorAll('input[name=scope]').forEach(x=>x.onchange=()=>{last=null;$('preview').style.display='none';$('empty').style.display='block'});load();</script></body></html>'''
(root/'master-limpeza.html').write_text(html,encoding='utf-8')

